namespace DonkAI;
// Dust2 callout zone of every grid cell (from the demos' place names); value = zone index + 1, 0 = unknown.
public static class Zones {
    static readonly byte[] Cells = System.Convert.FromBase64String("");
    public static int At(double x, double y) { var (cx, cy) = Nav.Cell(x, y); if (cx < 0 || cy < 0 || cx >= Grid.W || cy >= Grid.H) return -1; return Cells[cy * Grid.W + cx] - 1; }
}